const written = await parallel(JOBS.map(j=>()=>agent(j.prompt,{label:'write:'+j.key,phase:'Write',agentType:'Explore',schema:PAGE_SCHEMA,effort:'medium'}).then(r=>({key:j.key,pages:r?r.pages:[]}))))
phase('Fact-check')
const byIsland={maui:[],oahu:[]};
for(const w of written.filter(Boolean)) byIsland[w.key.startsWith('maui')?'maui':'oahu'].push(...w.pages);
const checks = await parallel(['maui','oahu'].map(isl=>()=>agent([
 'You are an adversarial fact-checker for these '+isl+' visitor-guide pages. Web-verify every CHECKABLE claim: laws (Act 104 details), reservation systems (Haleakala/recreation.gov, Hanauma Bay, Diamond Head, Haena), fees, drive times, transit (TheBus/Skyline lines), whale/turtle/seal viewing rules and distances (NOAA), surf seasons, cruise port names/piers, carrier coverage claims, anything post-2023-fire on West Maui. Also flag any sentence that calls ocean water safe. READ-ONLY.',
 'Return corrections with severity; empty list if all good. Pages JSON:',JSON.stringify(byIsland[isl])
].join('\n'),{label:'factcheck:'+isl,phase:'Fact-check',agentType:'Explore',schema:FACT_SCHEMA,effort:'high'}).then(c=>({island:isl,corrections:c?c.corrections:[]}))))
return { written, checks: checks.filter(Boolean) }